interface Pessoa {
  nome: string;
  idade: number;
}

// Funcionario tem tudo o que Pessoa tem, mais o que acrescenta
interface Funcionario extends Pessoa {
  salario: number;
}

interface Auditavel {
  criadoEm: string;
}

// uma interface pode estender várias ao mesmo tempo, separadas por vírgula
interface FuncionarioRegistado extends Pessoa, Auditavel {
  salario: number;
}

const ana: Funcionario = { nome: "Ana", idade: 34, salario: 1800 };

const bruno: FuncionarioRegistado = {
  nome: "Bruno",
  idade: 41,
  salario: 2100,
  criadoEm: "2024-03-01",
};

// @ts-expect-error falta idade, que vem herdada de Pessoa
const incompleto: Funcionario = { nome: "Carla", salario: 1500 };

console.log(ana.nome, ana.salario); // "Ana" 1800
console.log(bruno.criadoEm, bruno.idade); // "2024-03-01" 41
console.log(typeof incompleto); // "object"

type Pessoa = {
  nome: string;
  idade: number;
};

type ComEmail = {
  email: string;
};

// a interseção soma as duas formas: o valor tem de cumprir as duas
type Contacto = Pessoa & ComEmail;

const ana: Contacto = { nome: "Ana", idade: 34, email: "ana@exemplo.pt" };

// o mesmo resultado prático pelo caminho das interfaces
interface PessoaI {
  nome: string;
  idade: number;
}

interface ContactoI extends PessoaI {
  email: string;
}

const bruno: ContactoI = { nome: "Bruno", idade: 41, email: "bruno@exemplo.pt" };

// os dois tipos são intermutáveis: a estrutura é a mesma
const comoAlias: Contacto = bruno;
const comoInterface: ContactoI = ana;

console.log(comoAlias.email); // "bruno@exemplo.pt"
console.log(comoInterface.email); // "ana@exemplo.pt"

interface Produto {
  preco: number;
}

// @ts-expect-error extends recusa logo aqui: preco string não é compatível com preco number
interface ProdutoMau extends Produto {
  preco: string;
}

type ProdutoT = { preco: number };

// a interseção não se queixa: preco passou a ser number & string, ou seja never
type ProdutoComposto = ProdutoT & { preco: string };

function lerPreco(p: ProdutoComposto): never {
  return p.preco;
}

// @ts-expect-error o erro só aparece agora: nenhum valor é atribuível a never
const tentativa: ProdutoComposto = { preco: 10 };

console.log(typeof lerPreco, typeof tentativa); // "function" "object"

type Identificavel = { id: string };
type ComTempo = { criadoEm: string; atualizadoEm: string };
type ComAutor = { autorId: string };
type Publicavel = { publicado: boolean };

type Artigo = Identificavel & ComTempo & ComAutor & Publicavel & {
  titulo: string;
  corpo: string;
};

type Comentario = Identificavel & ComTempo & ComAutor & {
  artigoId: string;
  texto: string;
};

const artigo: Artigo = {
  id: "a1",
  criadoEm: "2024-01-10",
  atualizadoEm: "2024-01-12",
  autorId: "u7",
  publicado: true,
  titulo: "Compor tipos",
  corpo: "Peças pequenas montam-se de muitas maneiras.",
};

const comentario: Comentario = {
  id: "c1",
  criadoEm: "2024-01-11",
  atualizadoEm: "2024-01-11",
  autorId: "u9",
  artigoId: "a1",
  texto: "Muito útil.",
};

// uma função que só precisa do bloco Identificavel aceita os dois
function chave(x: Identificavel): string {
  return x.id;
}

console.log(chave(artigo), chave(comentario)); // "a1" "c1"
console.log(artigo.publicado, comentario.artigoId); // true "a1"

type Coordenadas = {
  latitude: number;
  longitude: number;
};

// uma interface pode estender um type alias de objeto
interface Morada extends Coordenadas {
  rua: string;
  cidade: string;
}

interface Contactavel {
  telefone: string;
}

// e um type alias pode fazer interseção com interfaces
type Loja = Morada & Contactavel & { nome: string };

const loja: Loja = {
  latitude: 41.54,
  longitude: -8.42,
  rua: "Rua Central 10",
  cidade: "Braga",
  telefone: "253000000",
  nome: "Casa do Café",
};

type Resposta = string | number;

// @ts-expect-error uma interface só estende formas de objeto, nunca uma união
interface RespostaI extends Resposta {
  ok: boolean;
}

console.log(loja.cidade, loja.nome); // "Braga" "Casa do Café"
console.log(loja.latitude, loja.telefone); // 41.54 "253000000"

type ConfigBase = {
  servidor: { host: string; porta: number };
  debug: boolean;
};

type ConfigRetry = {
  servidor: { timeout: number };
};

// servidor não é fundido campo a campo: fica { host, porta } & { timeout }
type Config = ConfigBase & ConfigRetry;

const completa: Config = {
  servidor: { host: "localhost", porta: 8080, timeout: 3000 },
  debug: false,
};

const parcial: Config = {
  // @ts-expect-error falta timeout: o objeto aninhado tem de cumprir os dois blocos
  servidor: { host: "localhost", porta: 8080 },
  debug: true,
};

console.log(completa.servidor.timeout, completa.debug); // 3000 false
console.log(typeof parcial); // "object"

interface Utilizador {
  id: string;
  email: string;
}

// extends: Administrador é um Utilizador especializado
interface Administrador extends Utilizador {
  permissoes: string[];
}

// interseção: capacidades independentes, somadas onde fizerem falta
type ComAuditoria = { criadoPor: string; criadoEm: string };

type AdministradorAuditado = Administrador & ComAuditoria;
type UtilizadorAuditado = Utilizador & ComAuditoria;

const admin: AdministradorAuditado = {
  id: "u1",
  email: "admin@exemplo.pt",
  permissoes: ["ler", "escrever"],
  criadoPor: "sistema",
  criadoEm: "2024-05-02",
};

const normal: UtilizadorAuditado = {
  id: "u2",
  email: "leitor@exemplo.pt",
  criadoPor: "admin@exemplo.pt",
  criadoEm: "2024-05-03",
};

console.log(admin.permissoes.length, admin.criadoPor); // 2 "sistema"
console.log(normal.email, normal.criadoEm); // "leitor@exemplo.pt" "2024-05-03"

