interface Veiculo {
  marca: string;
  ano: number;
}

interface Carro extends Veiculo {
  portas: number;
}

interface Mota extends Veiculo {
  cilindrada: number;
}

interface CarroEletrico extends Carro {
  autonomiaKm: number;
}

const carro: Carro = { marca: "Fiat", ano: 2020, portas: 5 };
const mota: Mota = { marca: "Honda", ano: 2019, cilindrada: 600 };
const eletrico: CarroEletrico = {
  marca: "Nissan",
  ano: 2023,
  portas: 5,
  autonomiaKm: 380,
};

function descrever(v: Veiculo): string {
  return `${v.marca} de ${v.ano}`;
}

console.log(descrever(carro), carro.portas); // "Fiat de 2020" 5
console.log(descrever(mota), mota.cilindrada); // "Honda de 2019" 600
console.log(descrever(eletrico), eletrico.autonomiaKm); // "Nissan de 2023" 380

type Identificavel = { id: string };
type Datado = { criadoEm: string };
type Nomeado = { nome: string };

type Cliente = Identificavel & Datado & Nomeado & { email: string };
type Etiqueta = Identificavel & Nomeado;

const cliente: Cliente = {
  id: "c1",
  criadoEm: "2024-06-01",
  nome: "Ana Dias",
  email: "ana@exemplo.pt",
};

const etiqueta: Etiqueta = { id: "e1", nome: "urgente" };

function rotular(x: Identificavel & Nomeado): string {
  return `${x.id}: ${x.nome}`;
}

console.log(rotular(cliente)); // "c1: Ana Dias"
console.log(rotular(etiqueta)); // "e1: urgente"
console.log(cliente.email, cliente.criadoEm); // "ana@exemplo.pt" "2024-06-01"

interface Encomenda {
  codigo: number;
}

// @ts-expect-error extends recusa de imediato: codigo string contra codigo number
interface EncomendaMa extends Encomenda {
  codigo: string;
}

type EncomendaT = { codigo: number };

// a interseção compila em silêncio: codigo ficou number & string, ou seja never
type EncomendaComposta = EncomendaT & { codigo: string };

function lerCodigo(e: EncomendaComposta): never {
  return e.codigo;
}

// @ts-expect-error nenhum valor pertence a never, nem 1 nem "1"
const impossivel: EncomendaComposta = { codigo: 1 };

// correção: a propriedade nova passa a ter um nome próprio
type EncomendaBoa = EncomendaT & { codigoExterno: string };

const boa: EncomendaBoa = { codigo: 1, codigoExterno: "EXT-0001" };

console.log(typeof lerCodigo, typeof impossivel); // "function" "object"
console.log(boa.codigo, boa.codigoExterno); // 1 "EXT-0001"

type Identificavel = { id: string };
type Datado = { criadoEm: string };
type Destinatario = { paraEmail: string };

interface Canal extends Identificavel {
  nome: string;
}

type NotificacaoEmail = Canal & Datado & Destinatario & {
  assunto: string;
  corpo: string;
};

const aviso: NotificacaoEmail = {
  id: "n1",
  nome: "email-transacional",
  criadoEm: "2024-08-15",
  paraEmail: "cliente@exemplo.pt",
  assunto: "Encomenda enviada",
  corpo: "A sua encomenda saiu do armazém.",
};

type ConfigBase = { envio: { tentativas: number } };
type ConfigRetry = { envio: { intervaloMs: number } };
type Config = ConfigBase & ConfigRetry;

const config: Config = { envio: { tentativas: 3, intervaloMs: 500 } };

const configParcial: Config = {
  // @ts-expect-error a composição é rasa: envio tem de cumprir os dois blocos de uma vez
  envio: { tentativas: 3 },
};

function resumo(n: Identificavel & Datado): string {
  return `${n.id} em ${n.criadoEm}`;
}

console.log(resumo(aviso), aviso.assunto); // "n1 em 2024-08-15" "Encomenda enviada"
console.log(config.envio.tentativas, config.envio.intervaloMs); // 3 500
console.log(typeof configParcial); // "object"
